<template><Card class="s1-ui s1-compact-list"><header class="ui-header"><div><h2>{{review?'商品审核':'商品监管'}}</h2><p>{{review?'核对当前送审内容版本；批准后仍由商户主动上架。':'审核、销售、库存和监管状态独立展示，不提供平台代商户上架。'}}</p></div></header><DatasetSwitch :available="demoAvailable" :all="showTestData" @change="switchDataset"/><PageStatus v-bind="$data"/><div class="ui-search"><label>商品名称<Input v-model="q" maxlength="100" placeholder="按商品名称搜索" @on-enter="search"/></label><label>所属商户<BusinessSelect v-model="targetStore" type="stores" @input="categoryId=''"/></label><label>商品类目<CategorySelect v-model="categoryId" purpose="goods" :store-id="targetStore"/></label><template v-if="!review"><label>审核状态<Select v-model="reviewStatus" clearable><Option v-for="v in ['DRAFT','SUBMITTED','APPROVED','REJECTED']" :key="v" :value="v">{{status(v)}}</Option></Select></label><label>销售状态<Select v-model="marketStatus" clearable><Option value="UPPER">已上架</Option><Option value="DOWN">已下架</Option></Select></label><label>库存状态<Select v-model="stockState" clearable><Option value="IN_STOCK">有可售库存</Option><Option value="OUT_OF_STOCK">缺货</Option><Option value="INCOMPLETE">资料不完整</Option></Select></label><label>监管状态<Select v-model="forced" clearable><Option value="true">受监管下架</Option><Option value="false">未受监管</Option></Select></label></template><div class="ui-actions"><Button type="primary" @click="search">查询</Button><Button @click="reset">重置</Button></div></div><Table class="s1-list-table" v-compact-table :columns="columns" :data="records" :loading="loading" no-data-text="没有符合条件的商品"><template slot="image" slot-scope="{row}"><ProductImage :file-id="row.galleryFileIds&&row.galleryFileIds[0]" :alt="row.name"/></template><template slot="name" slot-scope="{row}"><button class="ui-link ui-primary-name" @click="detail(row.id)">{{row.name||'未命名草稿'}}</button></template><template slot="price" slot-scope="{row}">{{money(row.priceCent)}}</template><template slot="state" slot-scope="{row}"><StatusTag :value="row.reviewStatus"/><StatusTag :value="row.marketStatus"/><Tag :color="row.forcedOff?'red':'default'">{{row.forcedOff?'受监管':'未受监管'}}</Tag><span class="ui-meta"> · {{status(row.stockState)}}</span></template><template slot="submitted" slot-scope="{row}">{{date(row.submittedAt)}} · <span class="ui-meta">内容 v{{row.contentVersion}}</span></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="detail(row.id)">{{review?'审核详情':'监管详情'}}</Button></template></Table><Page class="ui-pagination" :total="total" :current="page" :page-size="size" show-total @on-change="changePage"/></Card></template>
<script>import page from './page';import PageStatus from './components/PageStatus';import BusinessSelect from './components/BusinessSelect';import CategorySelect from './components/CategorySelect';import ProductImage from './components/ProductImage';import StatusTag from './components/StatusTag';const keys=['q','targetStore','categoryId','reviewStatus','marketStatus','stockState','forced'];export default {mixins:[page],components:{PageStatus,BusinessSelect,CategorySelect,ProductImage,StatusTag},props:{review:Boolean},data:()=>({q:'',targetStore:'',categoryId:'',reviewStatus:'',marketStatus:'',stockState:'',forced:'',columns:[{title:'主图',slot:'image',width:85},{title:'商品名称',slot:'name',minWidth:210},{title:'所属商户',key:'storeName',minWidth:200,tooltip:true},{title:'商品类目',key:'categoryPath',minWidth:220,tooltip:true},{title:'价格',slot:'price',width:110},{title:'审核／销售／监管／库存',slot:'state',minWidth:340},{title:'送审时间／版本',slot:'submitted',minWidth:190},{title:'操作',slot:'operations',width:115}]}),mounted(){this.initializeList(keys);this.reload();},methods:{reload(){return this.load(this.review?'/reviews':'/goods',{q:this.q||undefined,targetStore:this.targetStore||undefined,categoryId:this.categoryId||undefined,...(!this.review?{status:this.reviewStatus||undefined,marketStatus:this.marketStatus||undefined,stockState:this.stockState||undefined,forced:this.forced||undefined}:{})},true);},search(){this.page=1;this.remember(keys);this.reload();},reset(){keys.forEach(k=>{this[k]='';});this.search();},changePage(v){this.page=v;this.remember(keys);this.reload();}}};</script>
